#include <algorithm>
#include <array>
#include <concepts>
#include <iostream>
#include <optional>
#include <span>
#include <string_view>

template <std::totally_ordered T>
[[nodiscard]] constexpr T larger(T a, T b) {
  return b < a ? a : b;
}

struct Joint {
  std::string_view name;
  int motor_id;
};

[[nodiscard]] std::optional<int> motor_id(std::span<const Joint> joints, std::string_view name) {
  const auto it = std::ranges::find(joints, name, &Joint::name);
  if (it == joints.end()) return std::nullopt;
  return it->motor_id;
}

int main() {
  std::cout << larger(3, 7) << ' ' << larger(2.5, -1.0) << '\n';
  constexpr std::array joints{Joint{"shoulder", 1}, Joint{"elbow", 2}, Joint{"wrist", 3}};
  for (const std::string_view name : {"elbow", "gripper"}) {
    if (const std::optional<int> id = motor_id(joints, name)) {
      std::cout << name << ": motor " << *id << '\n';
    } else {
      std::cout << name << ": no motor\n";
    }
  }
}

