#include <concepts>
#include <string>

template <typename T>
T deduced(T value) {
  return value;
}

int main() {
  const int limit = 10;
  const int& ref = limit;
  const std::string name = "base_link";
  static_assert(std::same_as<decltype(deduced(limit)), int>);          // top-level const dropped
  static_assert(std::same_as<decltype(deduced(ref)), int>);            // the reference too
  static_assert(std::same_as<decltype(deduced("arm")), const char*>);  // the array decays to a pointer
  static_assert(std::same_as<decltype(deduced(name)), std::string>);   // a copy of name
}

