template <typename T>
class Samples {
 public:
  void add(T value) { values_.push_back(std::move(value)); }
  [[nodiscard]] std::ptrdiff_t count() const { return std::ssize(values_); }

  // Needs T{}, + and a conversion from an integer: fine for int, impossible for std::string.
  [[nodiscard]] std::optional<T> mean() const {
    if (values_.empty()) return std::nullopt;
    return std::accumulate(values_.begin(), values_.end(), T{}) / static_cast<T>(count());
  }

 private:
  std::vector<T> values_;
};

int main() {
  Samples<int> ranges_mm;
  for (const int r : {800, 900, 1300}) ranges_mm.add(r);
  if (const auto mean = ranges_mm.mean()) std::cout << ranges_mm.count() << " ranges, mean " << *mean << " mm\n";

  Samples<std::string> frames;
  frames.add("base_link");
  frames.add("laser");
  std::cout << frames.count() << " frames\n";
}

