  static_assert(std::same_as<decltype(timeout_ms), const std::optional<int>>);
  static_assert(std::same_as<decltype(names), const std::vector<const char*>>);
  static_assert(std::same_as<decltype(braces), const std::vector<std::vector<int>::const_iterator>>);
  static_assert(std::same_as<decltype(parens), const std::vector<int>>);
  std::cout << "braces hold " << braces.size() << " elements, parens hold " << parens.size() << '\n';
}

