template <typename T, std::size_t N>
  requires(N > 0)
class LastN {
 public:
  void push(T value) {
    values_[next_] = std::move(value);
    next_ = (next_ + 1) % capacity;
    if (count_ < capacity) ++count_;
  }

  [[nodiscard]] std::ptrdiff_t size() const { return count_; }

  [[nodiscard]] std::optional<T> newest() const {
    if (count_ == 0) return std::nullopt;
    return values_[(next_ + capacity - 1) % capacity];
  }

  [[nodiscard]] std::optional<double> mean() const
    requires std::integral<T> || std::floating_point<T>
  {
    if (count_ == 0) return std::nullopt;
    const double sum = std::accumulate(values_.begin(), values_.begin() + count_, 0.0);
    return sum / static_cast<double>(count_);
  }

 private:
  static constexpr auto capacity = static_cast<std::ptrdiff_t>(N);
  std::array<T, N> values_{};
  std::ptrdiff_t next_ = 0;   // where the next push goes
  std::ptrdiff_t count_ = 0;  // how many values are held
};

template <typename B>
concept HasMean = requires(const B& b) { b.mean(); };

static_assert(HasMean<LastN<int, 3>>);
static_assert(!HasMean<LastN<std::string, 2>>);

int main() {
  LastN<int, 3> ranges_mm;
  for (const int r : {900, 850, 1300, 1250, 700}) ranges_mm.push(r);
  const auto newest = ranges_mm.newest();
  const auto mean = ranges_mm.mean();
  if (newest && mean) std::cout << std::format("size {}, newest {}, mean {:.1f}\n", ranges_mm.size(), *newest, *mean);

  LastN<std::string, 2> frames;
  for (const std::string_view frame : {"map", "odom", "base_link"}) frames.push(std::string(frame));
  if (const auto frame = frames.newest()) std::cout << std::format("size {}, newest {}\n", frames.size(), *frame);
}

