// The nearest obstacle in a scan, or nothing when the scan saw nothing.
[[nodiscard]] std::optional<int> nearest_mm(std::span<const int> ranges_mm) {
  if (ranges_mm.empty()) return std::nullopt;
  return std::ranges::min(ranges_mm);
}

int main() {
  const std::vector<int> scan{1200, 850, 3100};
  const std::vector<int> blind;
  if (const auto d = nearest_mm(scan)) std::cout << std::format("nearest {} mm\n", *d);

  const std::optional<int> none = nearest_mm(blind);
  std::cout << std::format("has a value: {}\n", none.has_value());
  try {
    std::cout << none.value() << '\n';
  } catch (const std::bad_optional_access& e) {
    std::cout << std::format("value() threw: {}\n", e.what());
  }
  std::cout << std::format("sizeof: optional<int> {}, optional<double> {}\n", sizeof(std::optional<int>),
                           sizeof(std::optional<double>));
}

