class Config {
 public:
  explicit Config(std::map<std::string, std::string, std::less<>> values) : values_(std::move(values)) {}

  [[nodiscard]] std::optional<std::string> get(std::string_view key) const {
    const auto it = values_.find(key);
    if (it == values_.end()) return std::nullopt;
    return it->second;
  }

  [[nodiscard]] std::optional<int> get_int(std::string_view key) const {
    const auto it = values_.find(key);
    if (it == values_.end()) return std::nullopt;
    const std::string& text = it->second;
    int value = 0;
    const auto [end, error] = std::from_chars(text.data(), text.data() + text.size(), value);
    if (error != std::errc{} || end != text.data() + text.size()) return std::nullopt;
    return value;
  }

 private:
  std::map<std::string, std::string, std::less<>> values_;
};

class LinkProbe {
 public:
  [[nodiscard]] int measure_latency_ms() {  // stands in for two seconds of pings
    ++probes_;
    return 180;
  }
  [[nodiscard]] int probes() const { return probes_; }

 private:
  int probes_ = 0;
};

int main() {
  const Config cfg({{"host", "robot-7.local"}, {"timeout_ms", "250"}, {"retries", "3"}, {"gain", "3x"}});
  LinkProbe probe;

  // 1. value_or returns a new std::string: keep it, don't view it.
  const std::string host = cfg.get("hostname").value_or("localhost.localdomain");

  // 2. As written, the fallback runs although the setting is there.
  const int as_written = cfg.get_int("timeout_ms").value_or(probe.measure_latency_ms());
  const int probes_as_written = probe.probes();
  // Fixed: the probe runs only when the setting is missing.
  const std::optional<int> configured = cfg.get_int("timeout_ms");
  const int timeout_ms = configured ? *configured : probe.measure_latency_ms();

  // 3. The key is misspelled, so the optional is empty and *retry was undefined behaviour.
  if (const std::optional<int> retries = cfg.get_int("retry")) {
    std::cout << std::format("retries {}\n", *retries);
  } else {
    std::cout << "retry is not set\n";
  }

  std::cout << std::format("host {}, timeout {} ms as written and {} ms after the fix\n", host, as_written, timeout_ms);
  std::cout << std::format("probes: {} as written, {} after the fix\n", probes_as_written,
                           probe.probes() - probes_as_written);
  std::cout << std::format("gain parses: {}\n", cfg.get_int("gain").has_value());
}

