#include <format>
#include <iostream>
#include <numbers>
#include <string>
#include <variant>
#include <vector>

struct Stop {};
struct Drive {
  double speed_mps;
};
struct Turn {
  double angle_rad;
};

using Command = std::variant<Stop, Drive, Turn>;

template <typename... Fs>
struct overloaded : Fs... {
  using Fs::operator()...;
};

struct Robot {
  double speed_mps = 0.0;
  double heading_rad = 0.0;
};

void apply(Robot& robot, const Command& cmd) {
  std::visit(overloaded{
                 [&](const Stop&) { robot.speed_mps = 0.0; },
                 [&](const Drive& d) { robot.speed_mps = d.speed_mps; },
                 [&](const Turn& t) { robot.heading_rad += t.angle_rad; },
             },
             cmd);
}

[[nodiscard]] std::string describe(const Command& cmd) {
  return std::visit(overloaded{
                        [](const Stop&) { return std::string("stop"); },
                        [](const Drive& d) { return std::format("drive at {:.2f} m/s", d.speed_mps); },
                        [](const Turn& t) { return std::format("turn by {:.3f} rad", t.angle_rad); },
                    },
                    cmd);
}

int main() {
  const std::vector<Command> plan{Drive{0.5}, Turn{std::numbers::pi / 2}, Drive{0.25}, Stop{}};
  Robot robot;
  for (const Command& cmd : plan) {
    apply(robot, cmd);
    std::cout << std::format("{:<22} speed {:.2f}, heading {:.3f}\n", describe(cmd), robot.speed_mps, robot.heading_rad);
  }
}

