#include <array>
#include <charconv>
#include <format>
#include <iostream>
#include <optional>
#include <string>
#include <string_view>
#include <system_error>
#include <variant>
#include <vector>

struct Temperature {
  double celsius;
};
struct Range {
  int mm;
};
struct Fault {
  std::string what;
};
using Reading = std::variant<Temperature, Range, Fault>;

template <typename... Fs>
struct overloaded : Fs... {
  using Fs::operator()...;
};

// The whole of text as a number, or nothing.
template <typename T>
[[nodiscard]] std::optional<T> to_number(std::string_view text) {
  T value{};
  const auto [end, error] = std::from_chars(text.data(), text.data() + text.size(), value);
  if (error != std::errc{} || end != text.data() + text.size()) return std::nullopt;
  return value;
}

[[nodiscard]] std::optional<Reading> parse(std::string_view line) {
  if (line.size() < 3 || line[1] != ' ') return std::nullopt;
  const std::string_view rest = line.substr(2);
  switch (line[0]) {
    case 'T':
      if (const auto c = to_number<double>(rest)) return Temperature{*c};
      return std::nullopt;
    case 'R':
      if (const auto mm = to_number<int>(rest)) return Range{*mm};
      return std::nullopt;
    case 'F':
      return Fault{std::string(rest)};
    default:
      return std::nullopt;
  }
}

struct Summary {
  std::optional<double> highest_celsius;
  std::optional<int> shortest_mm;
  std::vector<std::string> faults;
  int bad_lines = 0;
};

void add(Summary& s, const Reading& reading) {
  std::visit(overloaded{
                 [&](const Temperature& t) {
                   if (!s.highest_celsius || t.celsius > *s.highest_celsius) s.highest_celsius = t.celsius;
                 },
                 [&](const Range& r) {
                   if (!s.shortest_mm || r.mm < *s.shortest_mm) s.shortest_mm = r.mm;
                 },
                 [&](const Fault& f) { s.faults.push_back(f.what); },
             },
             reading);
}

int main() {
  constexpr std::array<std::string_view, 7> log{"T 21.5", "R 850", "T 24.0", "X 1", "R 430", "F wheel stalled", "R 4x0"};
  Summary s;
  for (const std::string_view line : log) {
    if (const std::optional<Reading> reading = parse(line)) {
      add(s, *reading);
    } else {
      ++s.bad_lines;
    }
  }
  if (s.highest_celsius) std::cout << std::format("highest {:.1f} C\n", *s.highest_celsius);
  if (s.shortest_mm) std::cout << std::format("shortest {} mm\n", *s.shortest_mm);
  for (const std::string& f : s.faults) std::cout << std::format("fault: {}\n", f);
  std::cout << std::format("bad lines: {}\n", s.bad_lines);
}
